    uniandes_dance_022_20/frame_aligned_videos/downscaled/448 \
    uniandes_dance_022_20/trajectory/gopro_calibs.csv \
    uniandes_dance_022_22/frame_aligned_videos/cam01.mp4 \
    uniandes_dance_022_22/frame_aligned_videos/cam02.mp4 \
    uniandes_dance_022_22/frame_aligned_videos/cam03.mp4 \
    uniandes_dance_022_22/frame_aligned_videos/cam04.mp4 \
